def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    out_rows = rows * 2
    out_cols = cols * 2

    result = [[0 for _ in range(out_cols)] for _ in range(out_rows)]

    # Top-left: copy original
    for r in range(rows):
        for c in range(cols):
            result[r][c] = grid[r][c]

    # Top-right: original flipped horizontally (mirror across vertical axis)
    for r in range(rows):
        for c in range(cols):
            result[r][out_cols - 1 - c] = grid[r][c]

    # Bottom-left: original flipped vertically (mirror across horizontal axis)  
    for r in range(rows):
        for c in range(cols):
            result[rows + r][c] = grid[rows - 1 - r][c]

    # Bottom-right: original flipped both ways (180° rotation equivalently)
    for r in range(rows):
        for c in range(cols):
            result[rows + r][out_cols - 1 - c] = grid[rows - 1 - r][cols - 1 - c]

    return result
